// OFF-04.6: client contracts of the ten Quality forms against a Python-signed SYNTHETIC fixture (OFF046_FIXTURE_JSON, generated by backend/tests/off046_fixture.py).
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { verifyOfflineScope } from "../lib/vinto/offline-scope-verify.ts";
import { verifyQualityPackage } from "../lib/vinto/offline-quality-verify.ts";
import {
    buildDraftPayload, bobbinContextVersion, contextIdFor, draftContextKey, editableFields, evaluateDraft, isCalculated, isLabEligible, parseBobbinContext, parseDraftPayload,
} from "../lib/vinto/offline-draft-schema.ts";
import { payloadHash } from "../lib/vinto/offline-sync-engine.ts";

const path = process.env.OFF046_FIXTURE_JSON;
if (!path) throw new Error("Python signed fixture required (OFF046_FIXTURE_JSON)");
const fx = JSON.parse(readFileSync(path, "utf8"));
const identity = fx.identity;
const scope = await verifyOfflineScope(fx.scope, fx.pin, identity);
const pkgs = {};
for (const f of [...fx.by_machine, ...fx.by_bobbin]) pkgs[f] = await verifyQualityPackage(fx.packages[f], { envelope: scope, trustedPublicKey: fx.pin }, identity);
const all = Object.keys(pkgs);

test("all ten signed packages verify and are lab-eligible (synthetic, captures disabled)", () => {
    assert.equal(all.length, 10);
    for (const f of all) {
        const p = pkgs[f].envelope.payload;
        assert.equal(p.captures_enabled, false, f);
        assert.equal(isLabEligible(p.definition), true, f);
        assert.equal(p.form_code, f);
    }
});

test("valid values normalise per form; calculated fields are never editable and never stored", () => {
    for (const f of all) {
        const def = pkgs[f].envelope.payload.definition;
        const r = evaluateDraft(def, fx.expected[f].values);
        assert.deepEqual(r.typeIssues, [], f);
        assert.deepEqual(r.requiredMissing ?? [], [], f);
        for (const field of editableFields(def)) assert.equal(isCalculated(field), false, f + ":" + field.key);
        for (const key of Object.keys(fx.expected[f].calculated)) {
            assert.equal(Object.hasOwn(fx.expected[f].values, key), false, f + ":" + key);
            const calc = def.fields.find(x => x.key === key);
            assert.ok(calc && isCalculated(calc), f + ":" + key);
        }
    }
});

test("a value sent for a calculated field is refused by the client schema", () => {
    for (const f of all) {
        const def = pkgs[f].envelope.payload.definition;
        const key = def.fields.find(isCalculated)?.key;
        if (!key) continue;
        const r = evaluateDraft(def, { ...fx.expected[f].values, [key]: "1" });
        assert.ok(r.typeIssues.some(i => i.key === key && i.code === "calculated"), f);
    }
});

test("bobbin context parses strictly and its version equals the backend's", async () => {
    const b = parseBobbinContext(fx.bobbin);
    assert.throws(() => parseBobbinContext({ ...fx.bobbin, extra: "x" }));
    assert.throws(() => parseBobbinContext({ ...fx.bobbin, context_digest: "zz" }));
    const snapshot = scope.payload.snapshot_id;
    for (const f of fx.by_bobbin) assert.equal(await bobbinContextVersion(snapshot, b.bobbin_id, b.context_digest), fx.expected[f].context_version, f);
});

test("context key separates machine forms from bobbin forms and one bobbin from another", () => {
    const b = parseBobbinContext(fx.bobbin);
    assert.equal(draftContextKey("VINTO-P1-22", undefined), "VINTO-P1-22");
    assert.equal(draftContextKey("VINTO-P1-21", b), "VINTO-P1-21@b:" + b.bobbin_id);
    assert.notEqual(draftContextKey("VINTO-P1-21", b), draftContextKey("VINTO-P1-21", { ...b, bobbin_id: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb" }));
});

test("draft payload carries the bobbin only for by-bobbin forms and parses back strictly", () => {
    const b = parseBobbinContext(fx.bobbin);
    const now = "2026-11-19T10:00:00.000Z";
    const id = "11111111-1111-4111-8111-111111111111";
    for (const f of all) {
        const src = { pkg: pkgs[f].envelope.payload, ownerId: identity.ownerId, deviceKey: identity.deviceKey };
        const byBobbin = fx.by_bobbin.includes(f);
        const d = buildDraftPayload(src, id, fx.expected[f].values, 1, now, now, byBobbin ? b : undefined);
        const back = parseDraftPayload(JSON.parse(JSON.stringify(d)));
        assert.equal("bobbin_context" in back, byBobbin, f);
        assert.throws(() => parseDraftPayload({ ...d, extra: 1 }), f);
    }
});

test("context ids are distinct per form (one signed scope, ten forms)", async () => {
    const ids = new Set();
    for (const f of all) ids.add(await contextIdFor(scope.payload.snapshot_id, "MP1", f));
    assert.equal(ids.size, 10);
});

test("payload hash equals the backend's canonical hash (bobbin reference inside the hashed content)", async () => {
    const b = parseBobbinContext(fx.bobbin);
    for (const f of all) {
        const content = { synthetic: true, payload: fx.expected[f].values, ...(fx.by_bobbin.includes(f) ? { bobbin: { bobbin_id: b.bobbin_id, context_digest: b.context_digest } } : {}) };
        assert.equal(await payloadHash(content), fx.expected[f].payload_sha256, f);
    }
});
